const listQuotes = `-- name: ListQuotes :many
SELECT q.uuid, q.purpose, q.status, q.starts_at, q.ends_at, q.channel, q.billing_days, q.currency, q.total,
    q.difference, q.valid_until, q.created_at,
    p.uuid AS product_uuid, p.code AS product_code, p.title AS product_title,
    pb.uuid AS pickup_branch_uuid, pb.code AS pickup_branch_code, pb.name AS pickup_branch_name,
    rb.uuid AS return_branch_uuid, rb.code AS return_branch_code, rb.name AS return_branch_name,
    c.uuid AS customer_uuid, c.customer_type, c.first_name AS customer_first_name, c.last_name AS customer_last_name,
    c.company_title AS customer_company_title,
    r.uuid AS reservation_uuid, r.reference AS reservation_reference,
    COUNT(*) OVER ()::bigint AS total_count
FROM quotes q
JOIN rental_products p ON p.organization_id = q.organization_id AND p.id = q.rental_product_id
JOIN branches pb ON pb.organization_id = q.organization_id AND pb.id = q.pickup_branch_id
JOIN branches rb ON rb.organization_id = q.organization_id AND rb.id = q.return_branch_id
LEFT JOIN customers c ON c.organization_id = q.organization_id AND c.id = q.customer_id
LEFT JOIN reservations r ON r.organization_id = q.organization_id AND r.id = q.reservation_id
WHERE q.organization_id = $1
  AND p.organization_id = $1
  AND pb.organization_id = $1
  AND rb.organization_id = $1
  AND (
    $2::bigint[] IS NULL
    OR q.pickup_branch_id = ANY($2::bigint[])
    OR q.return_branch_id = ANY($2::bigint[])
  )
  AND ($3::text[] IS NULL OR q.purpose = ANY($3::text[]))
  AND ($4::text[] IS NULL OR q.status = ANY($4::text[]))
  AND ($5::uuid[] IS NULL OR p.uuid = ANY($5::uuid[]))
  AND ($6::text[] IS NULL OR q.channel = ANY($6::text[]))
  AND ($7::uuid[] IS NULL OR r.uuid = ANY($7::uuid[]))
  AND (
    $8::text IS NULL
    OR p.code ILIKE '%' || $8 || '%'
    OR p.title ILIKE '%' || $8 || '%'
    OR c.company_title ILIKE '%' || $8 || '%'
    OR (c.first_name || ' ' || c.last_name) ILIKE '%' || $8 || '%'
    OR r.reference ILIKE '%' || $8 || '%'
  )
ORDER BY
    CASE WHEN $9::text = 'total' AND NOT $10::boolean THEN q.total END ASC,
    CASE WHEN $9::text = 'total' AND $10::boolean THEN q.total END DESC,
    CASE WHEN $9::text = 'starts_at' AND NOT $10::boolean THEN q.starts_at END ASC,
    CASE WHEN $9::text = 'starts_at' AND $10::boolean THEN q.starts_at END DESC,
    CASE WHEN $9::text = 'valid_until' AND NOT $10::boolean THEN q.valid_until END ASC,
    CASE WHEN $9::text = 'valid_until' AND $10::boolean THEN q.valid_until END DESC,
    CASE WHEN $9::text = 'created_at' AND NOT $10::boolean THEN q.created_at END ASC,
    CASE WHEN $9::text = 'created_at' AND $10::boolean THEN q.created_at END DESC,
    q.id DESC
LIMIT $12 OFFSET $11
`

